(function(){'use strict';var state={results:null,history:[]};var elements={};

function qs(s){return document.querySelector(s)}
function qsa(s){return document.querySelectorAll(s)}

function init(){elements={input:document.getElementById('html-input'),processBtn:document.getElementById('minify-btn'),resetBtn:document.getElementById('reset-btn'),resultArea:document.getElementById('result-area'),emptyState:document.getElementById('empty-state'),statusBadge:document.getElementById('status-badge'),resultText:document.getElementById('result-text'),statOriginal:document.getElementById('stat-original'),statMinified:document.getElementById('stat-minified'),statSavings:document.getElementById('stat-savings'),statSavingsBytes:document.getElementById('stat-savings-bytes'),exportSection:document.getElementById('export-section'),exportCopy:document.getElementById('export-copy'),exportTxt:document.getElementById('export-txt'),exportJson:document.getElementById('export-json'),exportPrint:document.getElementById('export-print'),comparisonSection:document.getElementById('comparison-section'),comparisonSelect:document.getElementById('comparison-select'),comparisonTable:document.getElementById('comparison-table'),historySection:document.getElementById('history-section'),historyList:document.getElementById('history-list'),savingsGauge:document.getElementById('savings-gauge'),gaugeValue:document.getElementById('gauge-value'),gaugeLabel:document.getElementById('gauge-label'),gaugeGrade:document.getElementById('gauge-grade'),optionsToggle:document.getElementById('options-toggle'),optionsPanel:document.getElementById('options-panel')};
elements.processBtn.addEventListener('click',process);elements.resetBtn.addEventListener('click',reset);elements.input.addEventListener('input',onInput);
if(elements.exportCopy)elements.exportCopy.addEventListener('click',exportCopy);if(elements.exportTxt)elements.exportTxt.addEventListener('click',exportTxt);if(elements.exportJson)elements.exportJson.addEventListener('click',exportJson);if(elements.exportPrint)elements.exportPrint.addEventListener('click',exportPrint);if(elements.comparisonSelect)elements.comparisonSelect.addEventListener('change',onComparisonChange);
if(elements.optionsToggle){elements.optionsToggle.addEventListener('click',function(){var expanded=elements.optionsToggle.getAttribute('aria-expanded')==='true';elements.optionsToggle.setAttribute('aria-expanded',!expanded);if(elements.optionsPanel){elements.optionsPanel.classList.toggle('open',!expanded);}});}
showEmptyState();}

function getOpt(id){var el=document.getElementById(id);return el?el.checked:true;}
function getMode(){var el=document.querySelector('input[name="opt-mode"]:checked');return el?el.value:'safe';}

function onInput(){updateStatus(elements.input.value.trim().length>0?'ready':'',elements.input.value.trim().length>0?'Ready':'');}
function updateStatus(type,text){if(elements.statusBadge){elements.statusBadge.className='status-badge'+(type?' '+type:'');elements.statusBadge.textContent=text;}}
function showEmptyState(){if(elements.emptyState)elements.emptyState.style.display='flex';if(elements.resultArea)elements.resultArea.style.display='none';}
function showResults(){if(elements.emptyState)elements.emptyState.style.display='none';if(elements.resultArea){elements.resultArea.style.display='block';elements.resultArea.classList.add('show');}}

function analyzeHTML(html){
  var cssRx=html.match(/<style[^>]*>([\s\S]*?)<\/style>/gi)||[];
  var jsRx=html.match(/<script[^>]*>([\s\S]*?)<\/script>/gi)||[];
  var cssSize=cssRx.reduce(function(s,b){var i=b.replace(/^<style[^>]*>/i,'').replace(/<\/style>$/i,'');return s+i.length;},0);
  var jsSize=jsRx.reduce(function(s,b){var i=b.replace(/^<script[^>]*>/i,'').replace(/<\/script>$/i,'');return s+i.length;},0);
  return{totalSize:html.length,cssSize:cssSize,jsSize:jsSize,htmlSize:html.length-cssSize-jsSize,commentCount:(html.match(/<!--[\s\S]*?-->/g)||[]).length,whitespaceCount:(html.match(/\s/g)||[]).length};
}

function fmtSize(s){return formatBytes(s)}

function displayReport(pre,post,ms){
  var sect=document.getElementById('report-section');if(!sect)return;
  sect.classList.add('show');
  var rHtmlB=document.getElementById('rpt-html-before');var rHtmlA=document.getElementById('rpt-html-after');var rHtmlP=document.getElementById('rpt-html-pct');
  var rCssB=document.getElementById('rpt-css-before');var rCssA=document.getElementById('rpt-css-after');var rCssP=document.getElementById('rpt-css-pct');
  var rJsB=document.getElementById('rpt-js-before');var rJsA=document.getElementById('rpt-js-after');var rJsP=document.getElementById('rpt-js-pct');
  var rComments=document.getElementById('rpt-comments');var rWs=document.getElementById('rpt-whitespace');var rTime=document.getElementById('rpt-time');var rStatus=document.getElementById('rpt-status');
  var htmlRed=pre.htmlSize-post.htmlSize;var htmlPct=pre.htmlSize>0?Math.round(htmlRed/pre.htmlSize*100):0;
  var cssRed=pre.cssSize-post.cssSize;var cssPct=pre.cssSize>0?Math.round(cssRed/pre.cssSize*100):0;
  var jsRed=pre.jsSize-post.jsSize;var jsPct=pre.jsSize>0?Math.round(jsRed/pre.jsSize*100):0;
  var commentsRemoved=pre.commentCount-post.commentCount;
  var whitespaceRemoved=pre.whitespaceCount-post.whitespaceCount;
  if(rHtmlB)rHtmlB.textContent=fmtSize(pre.htmlSize);if(rHtmlA)rHtmlA.textContent=fmtSize(post.htmlSize);if(rHtmlP){rHtmlP.textContent=htmlPct+'%';rHtmlP.className='report-pct'+(htmlPct>=50?' good':htmlPct>=20?' ok':htmlPct>=5?' fair':' low');}
  if(rCssB)rCssB.textContent=fmtSize(pre.cssSize);if(rCssA)rCssA.textContent=fmtSize(post.cssSize);if(rCssP){rCssP.textContent=cssPct+'%';rCssP.className='report-pct'+(cssPct>=50?' good':cssPct>=20?' ok':cssPct>=5?' fair':' low');}
  if(rJsB)rJsB.textContent=fmtSize(pre.jsSize);if(rJsA)rJsA.textContent=fmtSize(post.jsSize);if(rJsP){rJsP.textContent=jsPct+'%';rJsP.className='report-pct'+(jsPct>=50?' good':jsPct>=20?' ok':jsPct>=5?' fair':' low');}
  if(rComments)rComments.innerHTML=commentsRemoved+' <span style="font-size:11px;color:#64748b;font-weight:400">removed</span>';
  if(rWs)rWs.innerHTML=formatBytes(whitespaceRemoved)+' <span style="font-size:11px;color:#64748b;font-weight:400">removed</span>';
  if(rTime)rTime.textContent=ms+' ms';
  if(rStatus){rStatus.innerHTML='<span class="status-ok">&#10003; Valid</span>';}
}

function process(){var input=elements.input.value.trim();if(!input){showToast('Please enter HTML code to minify','error');return;}
var opts={minifyCSS:getOpt('opt-minify-css'),minifyJS:getOpt('opt-minify-js'),removeComments:getOpt('opt-remove-comments'),collapseWhitespace:getOpt('opt-collapse-whitespace'),removeQuotes:getOpt('opt-remove-quotes'),booleanAttrs:getOpt('opt-boolean-attrs'),removeRedundant:getOpt('opt-remove-redundant'),preserveJSONLD:getOpt('opt-preserve-jsonld'),preserveTemplates:getOpt('opt-preserve-templates'),mode:getMode()};
updateStatus('processing','Minifying...');setTimeout(function(){try{var startTime=performance.now();var pre=analyzeHTML(input);var result=minifyHTML(input,opts);var post=analyzeHTML(result);var elapsed=Math.round((performance.now()-startTime)*10)/10;
var originalSize=input.length;var minifiedSize=result.length;var savings=originalSize>0?Math.round((1-minifiedSize/originalSize)*100):0;var savingsBytes=originalSize-minifiedSize;
elements.resultText.textContent=result;elements.statOriginal.textContent=formatBytes(originalSize);elements.statMinified.textContent=formatBytes(minifiedSize);elements.statSavings.textContent=savings+'%';elements.statSavingsBytes.textContent=formatBytes(savingsBytes);
state.results={originalSize:originalSize,minifiedSize:minifiedSize,savings:savings,savingsBytes:savingsBytes,result:result,input:input.substring(0,80)+(input.length>80?'...':''),timestamp:Date.now(),pre:pre,post:post,elapsed:elapsed};
if(state.history.length>=5)state.history.shift();state.history.push(state.results);
renderGauge(savings);showResults();updateStatus('done','Done');if(elements.exportSection)elements.exportSection.style.display='flex';renderComparison();renderHistory();
if(elements.gaugeGrade){var grade=savings>=60?'Exceptional':savings>=40?'Excellent':savings>=20?'Good':savings>=10?'Fair':'Minimal';elements.gaugeGrade.textContent=grade;}
displayReport(pre,post,elapsed);
var warnings=validateResult(result,input,opts,pre);if(warnings.length>0){showToast('Completed with warnings: '+warnings[0],'error');}}catch(e){showToast('Error: '+e.message,'error');updateStatus('error','Error');}},50);}

function minifyHTML(html,opts){
  var protectedBlocks=[];
  function saveBlock(m){protectedBlocks.push(m);return'\x00B'+protectedBlocks.length+'\x00';}
  function restoreBlock(str){return str.replace(/\x00B(\d+)\x00/g,function(_,i){return protectedBlocks[parseInt(i)-1];});}
  var result=html;

  result=result.replace(/<!--\[[\s\S]*?\]-->|<!\[endif\]-->/gi,saveBlock);

  if(opts.preserveTemplates){
    result=result.replace(/<\?(?:php|=|xml)[\s\S]*?\?>/gi,saveBlock);
    result=result.replace(/\{\{[\s\S]*?\}\}|\{\%[\s\S]*?\%\}|<\%[\s\S]*?\%>|\{\![\s\S]*?!\}|<\%=[\s\S]*?\%>|<\%-[\s\S]*?\%>/gi,saveBlock);
  }

  result=result.replace(/<(pre|code|textarea)(\s[^>]*)?>[\s\S]*?<\/\1>/gi,saveBlock);

  if(opts.preserveJSONLD){
    result=result.replace(/<script[^>]*type=['"]?application\/ld\+json['"]?[^>]*>[\s\S]*?<\/script>/gi,saveBlock);
  }

  result=result.replace(/<template[\s\S]*?<\/template>/gi,saveBlock);

  result=result.replace(/<(script|style)(\s[^>]*)?>[\s\S]*?<\/\1>/gi,function(match,tag){
    if(tag==='script'){
      if(!opts.minifyJS)return saveBlock(match);
      var inner=match.replace(/^<script[^>]*>/i,'').replace(/<\/script>$/i,'');
      var openTag=match.match(/^<script[^>]*>/i)[0];
      var minJS=minifyJSBlock(inner,opts.mode==='aggressive');
      return saveBlock(openTag+minJS+(minJS?'':'')+'</script>');
    }
    if(tag==='style'){
      if(!opts.minifyCSS)return saveBlock(match);
      var inner=match.replace(/^<style[^>]*>/i,'').replace(/<\/style>$/i,'');
      var openTag=match.match(/^<style[^>]*>/i)[0];
      var minCSS=minifyCSSBlock(inner,opts.mode==='aggressive');
      return saveBlock(openTag+minCSS+(minCSS?'':'')+'</style>');
    }
    return match;
  });

  if(window.HTMLMinifier&&typeof window.HTMLMinifier.minify==='function'){
    try{result=window.HTMLMinifier.minify(result,{
      removeComments:opts.removeComments,
      collapseWhitespace:opts.collapseWhitespace,
      collapseBooleanAttributes:opts.booleanAttrs,
      removeAttributeQuotes:opts.removeQuotes,
      removeRedundantAttributes:opts.removeRedundant,
      removeEmptyAttributes:opts.removeRedundant,
      removeOptionalTags:opts.mode==='aggressive',
      removeScriptTypeAttributes:true,
      removeStyleLinkTypeAttributes:true,
      minifyCSS:false,minifyJS:false,
      keepClosingSlash:true,
      useShortDoctype:opts.mode==='aggressive',
      sortAttributes:opts.mode==='aggressive',
      sortClassName:opts.mode==='aggressive',
      removeTagWhitespace:true,
      preventAttributesEscaping:true,
      processScripts:['text/html']
    });}catch(e){result=manualMinifyHTML(result,opts);}
  }else{result=manualMinifyHTML(result,opts);}

  result=restoreBlock(result);

  if(opts.collapseWhitespace){result=result.replace(/>\s+</g,'><');result=result.trim();}

  return result;
}

function manualMinifyHTML(html,opts){
  var result=html;
  if(opts.removeComments){result=result.replace(/<!--[\s\S]*?-->/g,'');}
  if(opts.collapseWhitespace){
    result=result.replace(/>\s+</g,'><');
    result=result.replace(/\s{2,}/g,' ');
    result=result.replace(/\s+(<|$)/g,'$1');
    result=result.replace(/(^|>)\s+/g,'$1');
  }
  result=result.replace(/<(script|style)([^>]*)>\s*<\/\1>/gi,'<$1$2></$1>');
  if(!opts.preserveJSONLD){
    result=result.replace(/type=(?:'|")?application\/ld\+json(?:'|")?/gi,'');
  }
  result=result.replace(/type=(?:'|")?text\/(?:javascript|css)(?:'|")?/gi,'');
  result=result.replace(/language=(?:'|")?javascript(?:'|")?/gi,'');
  if(opts.removeQuotes){
    result=result.replace(/(class|id|style|title|alt|name|value|placeholder|href|src|rel|type|width|height|lang|dir)=['"]?([^\s"'=<>\/]+)['"]?/gi,function(m,attr,val){
      if(/^[a-zA-Z0-9\-_\/:.%#@!?&=+~]+$/.test(val)){return attr+'='+val;}
      return m;
    });
  }
  if(opts.booleanAttrs){
    try{result=result.replace(/<(\w+)([^>]*?)\s+(selected|checked|disabled|readonly|required|noshade|reversed|nowrap|multiple|autofocus|formnovalidate|ismap|itemscope|loop|muted|playsinline|controls|async|defer|novalidate|open)\s*=\s*(?:'|")?\w+(?:'|")?([^>]*)>/gi,'<$1$2 $3$4>');}catch(e){}
    try{result=result.replace(/<(\w+)([^>]*?)\s+(selected|checked|disabled|readonly|required|noshade|reversed|nowrap|multiple|autofocus|formnovalidate|ismap|itemscope|loop|muted|playsinline|controls|async|defer|novalidate|open)([^>]*)>/gi,'<$1$2 $3$4>');}catch(e){}
  }
  if(opts.removeRedundant){
    result=result.replace(/type=['"]?text\/css['"]?/gi,'');
    result=result.replace(/type=['"]?text\/javascript['"]?/gi,'');
    result=result.replace(/<th([^>]*)>\s*<\/th>/gi,'<th$1></th>');
    result=result.replace(/<td([^>]*)>\s*<\/td>/gi,'<td$1></td>');
    result=result.replace(/<li([^>]*)>\s*<\/li>/gi,'<li$1></li>');
  }
  return result;
}

function shortColor(s){if(!s||s.length<3)return s;var c={'red':'#f00','green':'#0f0','blue':'#00f','white':'#fff','black':'#000','gray':'#808080','grey':'#808080','silver':'#c0c0c0','maroon':'#800000','purple':'#800080','fuchsia':'#f0f','lime':'#0f0','olive':'#808000','navy':'#000080','teal':'#008080','aqua':'#0ff','orange':'#ffa500','yellow':'#ff0'};var l=s.toLowerCase();if(c[l])return c[l];return s;}

function minifyCSSBlock(css,aggressive){
  if(!css||!css.trim())return css;
  if(window.csso){
    try{var ret=window.csso.minify(css,{restructure:aggressive,comments:false,usage:null}).css;if(typeof ret==='string')return ret;}catch(e){}
  }
  return css.replace(/\/\*[\s\S]*?\*\//g,'')
    .replace(/;{2,}/g,';')
    .replace(/\s*([{}:;,])\s*/g,'$1')
    .replace(/;}/g,'}')
    .replace(/\b0(?:px|em|rem|%|vh|vw|pt|pc|in|cm|mm|ex|ch|vmin|vmax|q)\b/g,'0')
    .replace(/#([0-9a-f])\1([0-9a-f])\2([0-9a-f])\3(?![0-9a-f])/gi,'#$1$2$3')
    .replace(/\b0+\.(\d+)\b/g,'.$1')
    .replace(/\b(\d+\.\d+?)0+\b/g,'$1')
    .replace(/\s{2,}/g,' ')
    .replace(/\s*;\s*;+/g,';')
    .trim();
}

function minifyJSBlock(js,aggressive){
  if(!js||!js.trim())return js;
  if(window.Terser){
    try{
      var opts={output:{beautify:false,comments:false}};
      if(aggressive){opts.compress={dead_code:true,drop_debugger:true,booleans:true,loops:true,unused:true,hoist_funs:false,if_return:true,join_vars:true,cascade:true,side_effects:true,warnings:false};opts.mangle={};opts.ecma=2020;}
      var result=window.Terser.minify(js,opts);
      if(result&&result.code)return result.code;
      if(result&&result.error)throw result.error;
    }catch(e){}
  }
  return js.replace(/\/\/[^\n]*/g,'')
    .replace(/\/\*[\s\S]*?\*\//g,'')
    .replace(/^\s*[\r\n]+/gm,'')
    .replace(/\s{2,}/g,' ')
    .replace(/\s*([{}()\[\];,:!?=><+\-*/%|&^~])\s*/g,'$1')
    .replace(/;\s*}/g,'}')
    .replace(/['"]?use strict['"]?;?/gi,'')
    .trim();
}

function validateResult(result,original,opts,pre){
  var warnings=[];
  if(!result||result.length===0){warnings.push('Empty result');return warnings;}
  if(result.length>original.length&&opts.collapseWhitespace){var oc=original.replace(/>\s+</g,'><').replace(/\s{2,}/g,' ');if(result.length>oc.length){warnings.push('Result larger than input');}}
  if(window.DOMParser){try{var doc=new DOMParser().parseFromString(result,'text/html');var errEl=doc.querySelector('parsererror');if(errEl){warnings.push('HTML structure may be invalid');}}catch(e){warnings.push('HTML parse error');}}
  var bal=(result.match(/</g)||[]).length-(result.match(/>/g)||[]).length;if(Math.abs(bal)>5&&opts.mode==='aggressive'){warnings.push('Unbalanced angle brackets');}
  return warnings;
}

function renderGauge(savings){var svg=elements.savingsGauge;if(!svg)return;var fill=svg.querySelector('.gauge-arc-fill');if(!fill)return;var totalLen=251.2;var offset=totalLen-(savings/100)*totalLen;fill.setAttribute('stroke-dasharray',totalLen);fill.setAttribute('stroke-dashoffset',Math.max(0,offset));var color=savings>=60?'#16a34a':savings>=40?'#22c55e':savings>=20?'#eab308':savings>=10?'#f97316':'#ef4444';fill.setAttribute('stroke',color);if(elements.gaugeValue)elements.gaugeValue.textContent=savings+'%';if(elements.gaugeLabel){var label=savings>=60?'Exceptional':savings>=40?'Excellent':savings>=20?'Good':savings>=10?'Fair':'Minimal';elements.gaugeLabel.textContent=label;elements.gaugeLabel.style.color=color;}}

function renderComparison(){if(!elements.comparisonSelect||!elements.comparisonTable)return;var available=state.history.filter(function(item){return!state.results||item.timestamp!==state.results.timestamp;});if(available.length===0){if(elements.comparisonSection)elements.comparisonSection.style.display='none';return;}
if(elements.comparisonSection)elements.comparisonSection.style.display='block';var html='<option value="">Select previous...</option>';available.forEach(function(item,i){html+='<option value="'+state.history.indexOf(item)+'">'+item.input+' ('+formatDate(item.timestamp)+')</option>';});elements.comparisonSelect.innerHTML=html;}
function onComparisonChange(){var idx=parseInt(elements.comparisonSelect.value);if(isNaN(idx)||!state.history[idx]||!state.results){elements.comparisonTable.innerHTML='';return;}
var prev=state.history[idx];var curr=state.results;var metrics=[{label:'Original Size',curr:formatBytes(curr.originalSize),prev:formatBytes(prev.originalSize)},{label:'Minified Size',curr:formatBytes(curr.minifiedSize),prev:formatBytes(prev.minifiedSize)},{label:'Savings',curr:curr.savings+'%',prev:prev.savings+'%'}];var html='<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr></thead><tbody>';metrics.forEach(function(m){var diff=m.label==='Savings'?curr.savings-prev.savings:curr.originalSize-prev.originalSize-(curr.minifiedSize-prev.minifiedSize);var arrow=diff>0?'<span class="comp-up">+'+diff+'</span>':diff<0?'<span class="comp-down">'+diff+'</span>':'<span class="comp-same">0</span>';html+='<tr><td>'+m.label+'</td><td>'+m.curr+'</td><td>'+m.prev+'</td><td>'+arrow+'</td></tr>';});html+='</tbody></table>';elements.comparisonTable.innerHTML=html;}
function renderHistory(){if(!elements.historyList)return;if(state.history.length<=1){if(elements.historySection)elements.historySection.style.display='none';return;}
if(elements.historySection)elements.historySection.style.display='block';var html='';for(var i=state.history.length-1;i>=0;i--){var item=state.history[i];var active=state.results&&item.timestamp===state.results.timestamp?' style="border-color:var(--color-primary);background:rgba(37,99,235,0.05)"':'';html+='<div class="history-item"'+active+'><div class="history-meta"><span class="history-time">'+formatDate(item.timestamp)+'</span><span class="history-size">'+formatBytes(item.originalSize)+' \u2192 '+formatBytes(item.minifiedSize)+'</span></div><div class="history-savings" style="color:'+(item.savings>=60?'#16a34a':item.savings>=40?'#22c55e':item.savings>=20?'#eab308':item.savings>=10?'#f97316':'#ef4444')+'">-'+item.savings+'%</div></div>';}
elements.historyList.innerHTML=html;}
function exportCopy(){if(!state.results)return;if(navigator.clipboard){navigator.clipboard.writeText(state.results.result).then(function(){showToast('Copied to clipboard!','success');});}else{fallbackCopy(state.results.result);}}
function exportTxt(){if(!state.results)return;var r=state.results;var text='HTML Minification Report\n========================\n\nOriginal Size: '+formatBytes(r.originalSize)+'\nMinified Size: '+formatBytes(r.minifiedSize)+'\nSavings: '+r.savings+'% ('+formatBytes(r.savingsBytes)+')\n\n--- Per-Component ---\nHTML: '+((r.pre&&r.post)?formatBytes(r.pre.htmlSize)+' \u2192 '+formatBytes(r.post.htmlSize):'N/A')+'\nCSS: '+((r.pre&&r.post)?formatBytes(r.pre.cssSize)+' \u2192 '+formatBytes(r.post.cssSize):'N/A')+'\nJS: '+((r.pre&&r.post)?formatBytes(r.pre.jsSize)+' \u2192 '+formatBytes(r.post.jsSize):'N/A')+'\nTime: '+r.elapsed+'ms\n\n--- Minified Output ---\n\n'+r.result;downloadFile('html-minified.txt',text,'text/plain');showToast('Downloaded TXT report','success');}
function exportJson(){if(!state.results)return;var obj={originalSize:state.results.originalSize,minifiedSize:state.results.minifiedSize,savings:state.results.savings,elapsed:state.results.elapsed,output:state.results.result,timestamp:new Date().toISOString()};if(state.results.pre){obj.pre=state.results.pre;obj.post=state.results.post;}var json=JSON.stringify(obj,null,2);downloadFile('html-minified.json',json,'application/json');showToast('Downloaded JSON report','success');}
function exportPrint(){window.print();}
function downloadFile(filename,content,mimeType){var blob=new Blob([content],{type:mimeType});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function fallbackCopy(text){var ta=document.createElement('textarea');ta.style.cssText='position:fixed;opacity:0';ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('Copied!','success');}catch(e){showToast('Failed to copy','error');}document.body.removeChild(ta);}
function reset(){elements.input.value='';state.results=null;state.history=[];if(elements.comparisonTable)elements.comparisonTable.innerHTML='';updateStatus('','');showEmptyState();if(elements.exportSection)elements.exportSection.style.display='none';if(elements.historySection)elements.historySection.style.display='none';var sect=document.getElementById('report-section');if(sect)sect.classList.remove('show');}
function formatBytes(bytes){if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}
function formatDate(ts){var d=new Date(ts);return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
function showToast(msg,type){var existing=document.querySelector('.toast');if(existing)existing.remove();var el=document.createElement('div');el.className='toast '+(type||'info');el.textContent=msg;document.body.appendChild(el);setTimeout(function(){el.classList.add('show');},10);setTimeout(function(){el.classList.remove('show');setTimeout(function(){el.remove();},300);},3000);}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();
